import sympy

CONDITION_LABELS = [
    "H_1: Let F_p be the finite field with p elements",
    "H_2: Let R be the polynomial ring in one variable x over F_p",
    "H_3: Let I = (x^p - x) be the principal ideal generated by x^p - x in R",
    "¬Q: The factor ring R/I is NOT isomorphic to the direct product of p copies of F_p"
]

N_HYP = 3
NEG_Q_INDEX = 3

def conditions(witness) -> list[bool]:
    try:
        p = int(witness)
        if p < 2:
            return [False, False, False, False]
    except Exception:
        return [False, False, False, False]
        
    h1 = True
    h2 = True
    h3 = True
    
    try:
        neg_q = not sympy.isprime(p)
    except Exception:
        neg_q = False
        
    return [h1, h2, h3, neg_q]